# ==========================================================
# DYNAMIC HPC RESOURCE DETECTION
# ==========================================================

def parse_memory_value(value, default_unit="MB"):
    """
    Convert memory specifications to bytes.

    Supports:
        512
        512M
        512G
        512GB
        512T
        etc.
    """

    if value is None:
        return None

    value = str(value).strip()

    if not value:
        return None

    units = {
        "K": 1024,
        "KB": 1024,
        "M": 1024 ** 2,
        "MB": 1024 ** 2,
        "G": 1024 ** 3,
        "GB": 1024 ** 3,
        "T": 1024 ** 4,
        "TB": 1024 ** 4
    }

    upper = value.upper()

    for unit in sorted(units, key=len, reverse=True):
        if upper.endswith(unit):
            number = upper[:-len(unit)].strip()

            try:
                return int(float(number) * units[unit])
            except ValueError:
                return None

    try:
        number = float(upper)

        if default_unit in units:
            return int(number * units[default_unit])

    except ValueError:
        pass

    return None


def detect_cpu_count():
    """
    Detect CPUs actually available to the job.

    Priority:
        1. SLURM_CPUS_PER_TASK
        2. SLURM_CPUS_ON_NODE
        3. Linux CPU affinity
        4. os.cpu_count()
    """

    slurm_cpus = os.environ.get(
        "SLURM_CPUS_PER_TASK"
    )

    if slurm_cpus:
        try:
            cpus = int(slurm_cpus)

            if cpus > 0:
                return cpus

        except ValueError:
            pass

    slurm_cpus = os.environ.get(
        "SLURM_CPUS_ON_NODE"
    )

    if slurm_cpus:
        try:
            cpus = int(slurm_cpus)

            if cpus > 0:
                return cpus

        except ValueError:
            pass

    try:
        affinity = os.sched_getaffinity(0)

        if affinity:
            return len(affinity)

    except (AttributeError, OSError):
        pass

    return os.cpu_count() or 1


def detect_memory_bytes():
    """
    Detect memory available to the HPC job.

    Priority:
        1. SLURM_MEM_PER_NODE
        2. SLURM_MEM_PER_CPU * allocated CPUs
        3. /proc/meminfo
    """

    cpus = detect_cpu_count()

    # ------------------------------------------------------
    # SLURM memory per node
    # ------------------------------------------------------

    slurm_mem = os.environ.get(
        "SLURM_MEM_PER_NODE"
    )

    if slurm_mem:

        memory = parse_memory_value(
            slurm_mem,
            default_unit="MB"
        )

        if memory:
            return memory

    # ------------------------------------------------------
    # SLURM memory per CPU
    # ------------------------------------------------------

    slurm_mem = os.environ.get(
        "SLURM_MEM_PER_CPU"
    )

    if slurm_mem:

        memory_per_cpu = parse_memory_value(
            slurm_mem,
            default_unit="MB"
        )

        if memory_per_cpu:
            return memory_per_cpu * cpus

    # ------------------------------------------------------
    # Linux system memory
    # ------------------------------------------------------

    meminfo = "/proc/meminfo"

    if os.path.exists(meminfo):

        try:

            with open(
                meminfo,
                "r",
                encoding="utf-8"
            ) as handle:

                for line in handle:

                    if line.startswith(
                        "MemTotal:"
                    ):

                        kb = int(
                            line.split()[1]
                        )

                        return kb * 1024

        except Exception:
            pass

    return None


def format_gb(bytes_value):
    """
    Human-readable GB representation.
    """

    if bytes_value is None:
        return "unknown"

    return (
        f"{bytes_value / (1024 ** 3):.1f} GB"
    )


def detect_temp_directory():
    """
    Prefer node-local scratch space on HPC systems.
    """

    candidates = []

    slurm_tmpdir = os.environ.get(
        "SLURM_TMPDIR"
    )

    if slurm_tmpdir:
        candidates.append(
            slurm_tmpdir
        )

    custom_tmp = os.environ.get(
        "DUCKDB_TMPDIR"
    )

    if custom_tmp:
        candidates.append(
            custom_tmp
        )

    system_tmp = os.environ.get(
        "TMPDIR"
    )

    if system_tmp:
        candidates.append(
            system_tmp
        )

    candidates.append(
        tempfile.gettempdir()
    )

    candidates.append(
        OUTPUT_DIR
    )

    for directory in candidates:

        if not directory:
            continue

        try:

            Path(directory).mkdir(
                parents=True,
                exist_ok=True
            )

            if os.access(
                directory,
                os.W_OK
            ):
                return os.path.abspath(
                    directory
                )

        except Exception:
            continue

    return os.getcwd()


def configure_resources():
    """
    Determine resources dynamically.

    Optional manual overrides:

        BALANCE_THREADS
        BALANCE_MEMORY_GB
        DUCKDB_TMPDIR
    """

    detected_cpus = detect_cpu_count()
    detected_memory = detect_memory_bytes()

    # ------------------------------------------------------
    # CPU override
    # ------------------------------------------------------

    threads_env = os.environ.get(
        "BALANCE_THREADS"
    )

    if threads_env:

        try:
            threads = max(
                1,
                int(threads_env)
            )

        except ValueError:

            threads = detected_cpus

    else:

        threads = detected_cpus

    # ------------------------------------------------------
    # Memory
    # ------------------------------------------------------

    memory_env = os.environ.get(
        "BALANCE_MEMORY_GB"
    )

    if memory_env:

        try:

            memory_limit_gb = float(
                memory_env
            )

        except ValueError:

            memory_limit_gb = None

    else:

        memory_limit_gb = None

    if memory_limit_gb is None:

        if detected_memory:

            # Keep a safety margin for:
            # - Python
            # - operating system
            # - filesystem
            # - DuckDB overhead
            memory_limit_gb = (
                detected_memory
                / (1024 ** 3)
                * 0.88
            )

        else:

            # Conservative fallback
            memory_limit_gb = 8.0

    memory_limit_gb = max(
        1.0,
        memory_limit_gb
    )

    temp_directory = (
        detect_temp_directory()
    )

    return {
        "threads": threads,
        "detected_cpus": detected_cpus,
        "detected_memory": detected_memory,
        "memory_limit_gb": memory_limit_gb,
        "temp_directory": temp_directory
    }


# ==========================================================
# SQL HELPERS
# ==========================================================

def sql_string(value):
    """
    Safely quote a Python string for DuckDB SQL.
    """

    return "'" + str(value).replace(
        "'",
        "''"
    ) + "'"


def sql_identifier(value):
    """
    Safely quote an SQL identifier.
    """

    return '"' + str(value).replace(
        '"',
        '""'
    ) + '"'


def read_csv_expression(path):
    """
    optimized configuration to read csv for DuckDB
    """
    return (
        f"read_csv("
        f"{sql_string(path)}, "
        f"header=true, "
        f"auto_detect=true, "
        f"all_varchar=true, "
        f"parallel=true, "
        f"quote='\"', "
        f"ignore_errors=true"
        f")"
    )


def identifier_expression(column):
    """
    Equivalent in purpose to pandas to_numeric() followed
    by nullable integer normalization.

    PubChem AID/CID values are safely represented as BIGINT.
    """

    col = sql_identifier(column)

    return (
        f"CAST("
        f"TRY_CAST("
        f"TRIM(CAST({col} AS VARCHAR)) "
        f"AS DOUBLE"
        f") AS BIGINT)"
    )


def text_expression(column):
    """
    Equivalent to the original normalize_text_series().
    """

    col = sql_identifier(column)

    return (
        "CASE "
        f"WHEN {col} IS NULL THEN NULL "
        f"WHEN TRIM(CAST({col} AS VARCHAR)) = '' THEN NULL "
        f"WHEN LOWER(TRIM(CAST({col} AS VARCHAR))) "
        "IN ('nan', 'none', '<na>') THEN NULL "
        f"ELSE TRIM(CAST({col} AS VARCHAR)) "
        "END"
    )


# ==========================================================
# FILE / SCHEMA UTILITIES
# ==========================================================

def get_csv_columns(connection, path):
    """
    Obtain CSV column names without loading the dataset.
    """

    query = (
        "SELECT * "
        f"FROM {read_csv_expression(path)} "
        "LIMIT 0"
    )

    result = connection.execute(
        query
    )

    return [
        description[0]
        for description in result.description
    ]


def validate_required_columns(
    columns,
    path,
    required_columns
):
    """
    Validate required columns.
    """

    missing = [
        column
        for column in required_columns
        if column not in columns
    ]

    if missing:

        raise ValueError(
            f"{path} is missing required "
            f"columns: {missing}"
        )


# ==========================================================
# HEARTBEAT
# ==========================================================

def execute_with_heartbeat(
    connection,
    query,
    label,
    interval=30
):
    """
    Execute a long DuckDB operation while printing a
    heartbeat so an HPC job never appears completely frozen.
    """

    start_time = time.time()

    stop_event = threading.Event()

    def heartbeat():

        while not stop_event.wait(
            interval
        ):

            elapsed = (
                time.time() - start_time
            )

            print(
                f"[RUNNING] {label} | "
                f"elapsed: "
                f"{elapsed / 60:.1f} min",
                flush=True
            )

    thread = threading.Thread(
        target=heartbeat,
        daemon=True
    )

    thread.start()

    try:

        connection.execute(
            query
        )

    finally:

        stop_event.set()
        thread.join(
            timeout=1
        )

    elapsed = (
        time.time() - start_time
    )

    print(
        f"[DONE] {label} | "
        f"time: {elapsed / 60:.2f} min",
        flush=True
    )

    return elapsed


# ==========================================================
# LOGGING
# ==========================================================

def append_log(text):

    with open(
        LOG_FILE,
        "w",
        encoding="utf-8"
    ) as handle:

        handle.write(text)


# ==========================================================
# MAIN
# ==========================================================

def main():

    pipeline_start = time.time()

    Path(
        OUTPUT_DIR
    ).mkdir(
        parents=True,
        exist_ok=True
    )

    print(
        "==========================================================",
        flush=True
    )

    print(
        "BALANCED INACTIVE DATASET EXTRACTION",
        flush=True
    )

    print(
        "DuckDB HPC-optimized implementation",
        flush=True
    )

    print(
        "==========================================================",
        flush=True
    )

    # ======================================================
    # CHECK DUCKDB
    # ======================================================

    try:

        import duckdb

    except ImportError:

        print(
            "[ERROR] DuckDB is not installed.",
            flush=True
        )

        print(
            "",
            flush=True
        )

        print(
            "Install it inside the site-specific Conda environment (pubchem_env) with:",
            flush=True
        )

        print(
            "    pip install duckdb",
            flush=True
        )

        sys.exit(1)

    print(
        f"[INFO] DuckDB version: "
        f"{duckdb.__version__}",
        flush=True
    )

    # ======================================================
    # RESOURCE DETECTION
    # ======================================================

    resources = configure_resources()

    threads = resources[
        "threads"
    ]

    detected_cpus = resources[
        "detected_cpus"
    ]

    detected_memory = resources[
        "detected_memory"
    ]

    memory_limit_gb = resources[
        "memory_limit_gb"
    ]

    temp_directory = resources[
        "temp_directory"
    ]

    print(
        "",
        flush=True
    )

    print(
        "--- HPC RESOURCE CONFIGURATION ---",
        flush=True
    )

    print(
        f"[INFO] CPUs detected/allocated : "
        f"{detected_cpus:,}",
        flush=True
    )

    print(
        f"[INFO] DuckDB threads          : "
        f"{threads:,}",
        flush=True
    )

    print(
        f"[INFO] Detected memory         : "
        f"{format_gb(detected_memory)}",
        flush=True
    )

    print(
        f"[INFO] DuckDB memory limit    : "
        f"{memory_limit_gb:.1f} GB",
        flush=True
    )

    print(
        f"[INFO] DuckDB temporary dir   : "
        f"{temp_directory}",
        flush=True
    )

    print(
        "",
        flush=True
    )

    print(
        "[INFO] Resource overrides available:",
        flush=True
    )

    print(
        "       BALANCE_THREADS",
        flush=True
    )

    print(
        "       BALANCE_MEMORY_GB",
        flush=True
    )

    print(
        "       DUCKDB_TMPDIR",
        flush=True
    )

    # ======================================================
    # CHECK INPUT FILES
    # ======================================================

    print(
        "",
        flush=True
    )

    print(
        "--- STEP 1: Checking input files ---",
        flush=True
    )

    for path in [
        ACTIVE_FILE,
        PRIORITY_INACTIVE_FILE,
        GIANT_INACTIVE_FILE
    ]:

        if not os.path.exists(path):

            raise SystemExit(
                f"[ERROR] File not found: "
                f"{path}"
            )

        size_gb = (
            os.path.getsize(path)
            / (1024 ** 3)
        )

        print(
            f"[INFO] {path} | "
            f"{size_gb:.2f} GB",
            flush=True
        )

    # ======================================================
    # CONNECT DUCKDB
    # ======================================================

    connection = duckdb.connect(
        database=":memory:"
    )

    connection.execute(
        f"PRAGMA threads = {threads}"
    )

    connection.execute(
        "SET preserve_insertion_order=false"
    )

    connection.execute(
        "SET enable_progress_bar=false"
    )

    connection.execute(
        "SET memory_limit = "
        + sql_string(
            f"{memory_limit_gb:.1f}GB"
        )
    )

    connection.execute(
        "SET temp_directory = "
        + sql_string(
            temp_directory
        )
    )

    # ======================================================
    # CHECK SCHEMAS
    # ======================================================

    active_columns = (
        get_csv_columns(
            connection,
            ACTIVE_FILE
        )
    )

    priority_columns = (
        get_csv_columns(
            connection,
            PRIORITY_INACTIVE_FILE
        )
    )

    giant_columns = (
        get_csv_columns(
            connection,
            GIANT_INACTIVE_FILE
        )
    )

    validate_required_columns(
        active_columns,
        ACTIVE_FILE,
        KEY_COLUMNS
    )

    validate_required_columns(
        priority_columns,
        PRIORITY_INACTIVE_FILE,
        KEY_COLUMNS
    )

    validate_required_columns(
        giant_columns,
        GIANT_INACTIVE_FILE,
        KEY_COLUMNS
    )

    # ======================================================
    # STEP 2: ACTIVE OBSERVATIONS
    # ======================================================

    print(
        "",
        flush=True
    )

    print(
        "--- STEP 2: Loading active observations ---",
        flush=True
    )

    active_target_expr = (
        text_expression(TARGET_COL)
        if TARGET_COL in active_columns
        else "NULL::VARCHAR"
    )

    active_ko_expr = (
        text_expression(KO_COL)
        if KO_COL in active_columns
        else "NULL::VARCHAR"
    )

    active_class_expr = (
        text_expression(CLASS_COL)
        if CLASS_COL in active_columns
        else "NULL::VARCHAR"
    )

    active_query = f"""
        CREATE TEMP TABLE active_annotations AS

        SELECT
            {identifier_expression("PUBCHEM_AID")}
                AS __BAL_AID,

            {identifier_expression("PUBCHEM_CID")}
                AS __BAL_CID,

            {active_target_expr}
                AS __BAL_TARGET,

            {active_ko_expr}
                AS __BAL_KO,

            {active_class_expr}
                AS __BAL_CLASS

        FROM {read_csv_expression(ACTIVE_FILE)}

        WHERE
            {identifier_expression("PUBCHEM_AID")}
                IS NOT NULL

            AND

            {identifier_expression("PUBCHEM_CID")}
                IS NOT NULL

        QUALIFY
            ROW_NUMBER() OVER (
                PARTITION BY
                    {identifier_expression("PUBCHEM_AID")},
                    {identifier_expression("PUBCHEM_CID")}
            ) = 1
    """

    execute_with_heartbeat(
        connection,
        active_query,
        "Loading active annotations"
    )

    total_active_observations = (
        connection.execute(
            """
            SELECT COUNT(*)
            FROM active_annotations
            """
        ).fetchone()[0]
    )

    requested_target_total = int(
        total_active_observations
        * RATIO_INACTIVE_PER_ACTIVE
    )

    print(
        f"[INFO] Active observations: "
        f"{total_active_observations:,}",
        flush=True
    )

    # ======================================================
    # ACTIVE ANNOTATION SETS
    # ======================================================

    print(
        "[INFO] Building active annotation sets...",
        flush=True
    )

    connection.execute(
        """
        CREATE TEMP TABLE active_targets AS

        SELECT DISTINCT
            __BAL_TARGET

        FROM active_annotations

        WHERE __BAL_TARGET IS NOT NULL
        """
    )

    connection.execute(
        """
        CREATE TEMP TABLE active_kos AS

        SELECT DISTINCT
            __BAL_KO

        FROM active_annotations

        WHERE __BAL_KO IS NOT NULL
        """
    )

    connection.execute(
        """
        CREATE TEMP TABLE active_classes AS

        SELECT DISTINCT
            __BAL_CLASS

        FROM active_annotations

        WHERE __BAL_CLASS IS NOT NULL
        """
    )

    target_count = (
        connection.execute(
            """
            SELECT COUNT(*)
            FROM active_targets
            """
        ).fetchone()[0]
    )

    ko_count = (
        connection.execute(
            """
            SELECT COUNT(*)
            FROM active_kos
            """
        ).fetchone()[0]
    )

    class_count = (
        connection.execute(
            """
            SELECT COUNT(*)
            FROM active_classes
            """
        ).fetchone()[0]
    )

    # ======================================================
    # STEP 3: PRIORITY-1
    # ======================================================

    print(
        "",
        flush=True
    )

    print(
        "--- STEP 3: Loading Priority-1 observations ---",
        flush=True
    )

    priority_query = f"""
        CREATE TEMP TABLE priority_1 AS

        SELECT *

        FROM (

            SELECT
                r.*,

                {identifier_expression("PUBCHEM_AID")}
                    AS __BAL_AID,

                {identifier_expression("PUBCHEM_CID")}
                    AS __BAL_CID

            FROM {read_csv_expression(PRIORITY_INACTIVE_FILE)} r
        )

        WHERE
            __BAL_AID IS NOT NULL

            AND

            __BAL_CID IS NOT NULL

        QUALIFY
            ROW_NUMBER() OVER (
                PARTITION BY
                    __BAL_AID,
                    __BAL_CID
            ) = 1
    """

    execute_with_heartbeat(
        connection,
        priority_query,
        "Loading Priority-1 observations"
    )

    priority_count = (
        connection.execute(
            """
            SELECT COUNT(*)
            FROM priority_1
            """
        ).fetchone()[0]
    )

    # ------------------------------------------------------
    # Priority 1 is mandatory.
    #
    # Therefore the final target is never smaller than P1.
    # ------------------------------------------------------

    target_total = max(
        requested_target_total,
        priority_count
    )

    remaining_slots = max(
        0,
        target_total - priority_count
    )

    print(
        "",
        flush=True
    )

    print(
        f"Nominal 1:1 inactive target : "
        f"{requested_target_total:,}",
        flush=True
    )

    print(
        f"Priority-1 observations     : "
        f"{priority_count:,}",
        flush=True
    )

    print(
        f"Final target                : "
        f"{target_total:,}",
        flush=True
    )

    print(
        f"Remaining fallback slots    : "
        f"{remaining_slots:,}",
        flush=True
    )

    print(
        f"Active exact targets        : "
        f"{target_count:,}",
        flush=True
    )

    print(
        f"Active KO groups            : "
        f"{ko_count:,}",
        flush=True
    )

    print(
        f"Active target classes       : "
        f"{class_count:,}",
        flush=True
    )

    # ======================================================
    # IF P1 ALREADY FILLS TARGET
    # ======================================================

    if remaining_slots == 0:

        print(
            "",
            flush=True
        )

        print(
            "[INFO] Priority-1 already fills "
            "the complete target.",
            flush=True
        )

    # ======================================================
    # STEP 4: GIANT INACTIVE MASTER
    # ======================================================

    else:

        print(
            "",
            flush=True
        )

        print(
            "--- STEP 4: Scanning giant inactive master ---",
            flush=True
        )

        print(
            "",
            flush=True
        )

        print(
            "PRIORITY ORDER:",
            flush=True
        )

        print(
            "  1. Active-branch Priority-1 observations",
            flush=True
        )

        print(
            "  2. Exact UniProtKB_ID",
            flush=True
        )

        print(
            "  3. Exact KO",
            flush=True
        )

        print(
            "  4. Exact Target_Class",
            flush=True
        )

        print(
            "  5. Random unrelated observation",
            flush=True
        )

        # --------------------------------------------------
        # Annotation expressions for giant master
        # --------------------------------------------------

        giant_target_expr = (
            text_expression(TARGET_COL)
            if TARGET_COL in giant_columns
            else "NULL::VARCHAR"
        )

        giant_ko_expr = (
            text_expression(KO_COL)
            if KO_COL in giant_columns
            else "NULL::VARCHAR"
        )

        giant_class_expr = (
            text_expression(CLASS_COL)
            if CLASS_COL in giant_columns
            else "NULL::VARCHAR"
        )

        # --------------------------------------------------
        # This is the main HPC operation.
        #
        # DuckDB:
        #   - reads the 75 GB CSV in parallel
        #   - performs duplicate removal
        #   - excludes P1
        #   - performs exact annotation joins
        #   - assigns priorities
        #
        # There is NO Python row-by-row iteration.
        # --------------------------------------------------

        fallback_query = f"""
            CREATE TEMP TABLE fallback_candidates AS

            WITH raw_master AS (

                SELECT
                    r.*,

                    {identifier_expression("PUBCHEM_AID")}
                        AS __BAL_AID,

                    {identifier_expression("PUBCHEM_CID")}
                        AS __BAL_CID,

                    {giant_target_expr}
                        AS __BAL_TARGET,

                    {giant_ko_expr}
                        AS __BAL_KO,

                    {giant_class_expr}
                        AS __BAL_CLASS

                FROM {read_csv_expression(GIANT_INACTIVE_FILE)} r
            ),

            valid_master AS (

                SELECT *

                FROM raw_master

                WHERE
                    __BAL_AID IS NOT NULL

                    AND

                    __BAL_CID IS NOT NULL
            ),

            without_priority_1 AS (

                SELECT m.*

                FROM valid_master m

                ANTI JOIN priority_1 p

                    ON
                        m.__BAL_AID = p.__BAL_AID

                        AND

                        m.__BAL_CID = p.__BAL_CID
            ),

            unique_master AS (

                SELECT *

                FROM without_priority_1

                QUALIFY
                    ROW_NUMBER() OVER (
                        PARTITION BY
                            __BAL_AID,
                            __BAL_CID
                    ) = 1
            )

            SELECT
                u.*,

                CASE

                    WHEN t.__BAL_TARGET IS NOT NULL
                        THEN 2

                    WHEN k.__BAL_KO IS NOT NULL
                        THEN 3

                    WHEN c.__BAL_CLASS IS NOT NULL
                        THEN 4

                    ELSE 5

                END AS __BAL_PRIORITY,

                md5(
                    CAST(__BAL_AID AS VARCHAR)
                    || '|'
                    || CAST(__BAL_CID AS VARCHAR)
                    || '|'
                    || '{RANDOM_SEED}'
                ) AS __BAL_RANDOM_KEY

            FROM unique_master u

            LEFT JOIN active_targets t

                ON
                    u.__BAL_TARGET =
                    t.__BAL_TARGET

            LEFT JOIN active_kos k

                ON
                    u.__BAL_KO =
                    k.__BAL_KO

            LEFT JOIN active_classes c

                ON
                    u.__BAL_CLASS =
                    c.__BAL_CLASS
        """

        execute_with_heartbeat(
            connection,
            fallback_query,
            "Scanning and prioritizing giant inactive master"
        )

        # ==================================================
        # PRIORITY COUNTS
        # ==================================================

        print(
            "",
            flush=True
        )

        print(
            "--- STEP 5: Evaluating fallback priorities ---",
            flush=True
        )

        priority_counts_result = (
            connection.execute(
                """
                SELECT
                    __BAL_PRIORITY,
                    COUNT(*) AS n

                FROM fallback_candidates

                GROUP BY
                    __BAL_PRIORITY

                ORDER BY
                    __BAL_PRIORITY
                """
            ).fetchall()
        )

        priority_counts = {
            2: 0,
            3: 0,
            4: 0,
            5: 0
        }

        for priority, count in (
            priority_counts_result
        ):

            priority_counts[
                int(priority)
            ] = int(count)

        print(
            f"[INFO] Priority 2 candidates: "
            f"{priority_counts[2]:,}",
            flush=True
        )

        print(
            f"[INFO] Priority 3 candidates: "
            f"{priority_counts[3]:,}",
            flush=True
        )

        print(
            f"[INFO] Priority 4 candidates: "
            f"{priority_counts[4]:,}",
            flush=True
        )

        print(
            f"[INFO] Priority 5 candidates: "
            f"{priority_counts[5]:,}",
            flush=True
        )

        # ==================================================
        # EXACT SAME HIERARCHICAL SELECTION LOGIC
        # ==================================================

        allocations = {
            2: 0,
            3: 0,
            4: 0,
            5: 0
        }

        slots_left = remaining_slots

        for priority in [
            2,
            3,
            4,
            5
        ]:

            take = min(
                priority_counts[priority],
                slots_left
            )

            allocations[
                priority
            ] = take

            slots_left -= take

        print(
            "",
            flush=True
        )

        print(
            "SELECTION ALLOCATION:",
            flush=True
        )

        print(
            f"  Priority 2 selected: "
            f"{allocations[2]:,}",
            flush=True
        )

        print(
            f"  Priority 3 selected: "
            f"{allocations[3]:,}",
            flush=True
        )

        print(
            f"  Priority 4 selected: "
            f"{allocations[4]:,}",
            flush=True
        )

        print(
            f"  Priority 5 selected: "
            f"{allocations[5]:,}",
            flush=True
        )

        print(
            f"  Total fallback selected: "
            f"{sum(allocations.values()):,}",
            flush=True
        )

        # ==================================================
        # STEP 6: FINAL DATASET
        # ==================================================

        print(
            "",
            flush=True
        )

        print(
            "--- STEP 6: Writing final balanced dataset ---",
            flush=True
        )

    # ======================================================
    # FINAL OUTPUT QUERY
    # ======================================================

    if remaining_slots == 0:

        final_query = f"""

            SELECT
                * EXCLUDE (
                    __BAL_AID,
                    __BAL_CID
                )

            FROM priority_1
        """

    else:

        n2 = allocations[2]
        n3 = allocations[3]
        n4 = allocations[4]
        n5 = allocations[5]

        final_query = f"""

            WITH ranked_fallback AS (

                SELECT
                    *,

                    ROW_NUMBER() OVER (

                        PARTITION BY
                            __BAL_PRIORITY

                        ORDER BY

                            CASE
                                WHEN __BAL_PRIORITY = 5
                                THEN __BAL_RANDOM_KEY
                                ELSE NULL
                            END,

                            __BAL_AID,

                            __BAL_CID

                    ) AS __BAL_RANK

                FROM fallback_candidates
            ),

            selected_fallback AS (

                SELECT *

                FROM ranked_fallback

                WHERE

                    (
                        __BAL_PRIORITY = 2
                        AND __BAL_RANK <= {n2}
                    )

                    OR

                    (
                        __BAL_PRIORITY = 3
                        AND __BAL_RANK <= {n3}
                    )

                    OR

                    (
                        __BAL_PRIORITY = 4
                        AND __BAL_RANK <= {n4}
                    )

                    OR

                    (
                        __BAL_PRIORITY = 5
                        AND __BAL_RANK <= {n5}
                    )
            )

            SELECT
                * EXCLUDE (
                    __BAL_AID,
                    __BAL_CID
                )

            FROM priority_1

            UNION ALL BY NAME

            SELECT
                * EXCLUDE (
                    __BAL_AID,
                    __BAL_CID,
                    __BAL_TARGET,
                    __BAL_KO,
                    __BAL_CLASS,
                    __BAL_PRIORITY,
                    __BAL_RANDOM_KEY,
                    __BAL_RANK
                )

            FROM selected_fallback
        """

    # ------------------------------------------------------
    # Remove stale temporary output
    # ------------------------------------------------------

    if os.path.exists(
        TEMP_OUTPUT_FILE
    ):

        os.remove(
            TEMP_OUTPUT_FILE
        )

    # ------------------------------------------------------
    # Write CSV
    # ------------------------------------------------------

    copy_query = f"""
        COPY (
            {final_query}
        )
        TO {sql_string(TEMP_OUTPUT_FILE)}
        WITH (
            FORMAT CSV,
            HEADER TRUE,
            DELIMITER ','
        )
    """

    execute_with_heartbeat(
        connection,
        copy_query,
        "Writing balanced inactive dataset"
    )

    # ======================================================
    # STEP 7: VALIDATION
    # ======================================================

    print(
        "",
        flush=True
    )

    print(
        "--- STEP 7: Final validation ---",
        flush=True
    )

    output_columns = get_csv_columns(
        connection,
        TEMP_OUTPUT_FILE
    )

    validate_required_columns(
        output_columns,
        TEMP_OUTPUT_FILE,
        KEY_COLUMNS
    )

    output_aid_expr = (
        identifier_expression(
            "PUBCHEM_AID"
        )
    )

    output_cid_expr = (
        identifier_expression(
            "PUBCHEM_CID"
        )
    )

    # ------------------------------------------------------
    # Output statistics
    # ------------------------------------------------------

    output_stats_query = f"""

        SELECT
            COUNT(*) AS total_rows,

            COUNT(
                DISTINCT
                CAST(
                    {output_aid_expr}
                    AS VARCHAR
                )
                || '|'
                ||
                CAST(
                    {output_cid_expr}
                    AS VARCHAR
                )
            ) AS unique_observations

        FROM {read_csv_expression(TEMP_OUTPUT_FILE)}
    """

    output_stats = (
        connection.execute(
            output_stats_query
        ).fetchone()
    )

    final_rows = int(
        output_stats[0]
    )

    final_unique = int(
        output_stats[1]
    )

    print(
        f"[INFO] Final rows: "
        f"{final_rows:,}",
        flush=True
    )

    print(
        f"[INFO] Final unique AID/CID observations: "
        f"{final_unique:,}",
        flush=True
    )

    # ------------------------------------------------------
    # Priority-1 retention
    # ------------------------------------------------------

    retention_query = f"""

        WITH final_keys AS (

            SELECT DISTINCT

                {output_aid_expr}
                    AS __BAL_AID,

                {output_cid_expr}
                    AS __BAL_CID

            FROM {read_csv_expression(TEMP_OUTPUT_FILE)}

            WHERE
                {output_aid_expr}
                    IS NOT NULL

                AND

                {output_cid_expr}
                    IS NOT NULL
        )

        SELECT

            COUNT(*) AS priority_total,

            COUNT(
                CASE
                    WHEN f.__BAL_AID IS NOT NULL
                    THEN 1
                END
            ) AS priority_retained

        FROM priority_1 p

        LEFT JOIN final_keys f

            ON
                p.__BAL_AID =
                f.__BAL_AID

                AND

                p.__BAL_CID =
                f.__BAL_CID
    """

    retention_result = (
        connection.execute(
            retention_query
        ).fetchone()
    )

    priority_total = int(
        retention_result[0]
    )

    priority_retained = int(
        retention_result[1]
    )

    if priority_total:

        retention_percentage = (
            priority_retained
            / priority_total
            * 100.0
        )

    else:

        retention_percentage = 100.0

    missing_priority = (
        priority_total
        - priority_retained
    )

    print(
        f"[INFO] Priority-1 total: "
        f"{priority_total:,}",
        flush=True
    )

    print(
        f"[INFO] Priority-1 retained: "
        f"{priority_retained:,}",
        flush=True
    )

    print(
        f"[INFO] Priority-1 retention: "
        f"{retention_percentage:.6f}%",
        flush=True
    )

    print(
        f"[INFO] Priority-1 missing from final: "
        f"{missing_priority:,}",
        flush=True
    )

    # ======================================================
    # VALIDATION FAILURES
    # ======================================================

    validation_errors = []

    if final_rows != target_total:

        validation_errors.append(
            "Final row count does not equal "
            "the requested target."
        )

    if final_unique != final_rows:

        validation_errors.append(
            "Duplicate AID/CID observations "
            "remain in the final dataset."
        )

    if priority_retained != priority_total:

        validation_errors.append(
            "Priority-1 retention is below 100%."
        )

    # ======================================================
    # SUCCESS / FAILURE
    # ======================================================

    if validation_errors:

        print(
            "",
            flush=True
        )

        print(
            "[ERROR] VALIDATION FAILED",
            flush=True
        )

        for error in validation_errors:

            print(
                f"[ERROR] {error}",
                flush=True
            )

        print(
            "",
            flush=True
        )

        print(
            "[ERROR] Temporary output retained at:",
            flush=True
        )

        print(
            f"        {TEMP_OUTPUT_FILE}",
            flush=True
        )

        connection.close()

        sys.exit(1)

    # ------------------------------------------------------
    # Atomic replacement
    # ------------------------------------------------------

    os.replace(
        TEMP_OUTPUT_FILE,
        BALANCED_INACTIVE_FILE
    )

    pipeline_time = (
        time.time()
        - pipeline_start
    )

    # ======================================================
    # LOG
    # ======================================================

    log_content = f"""
==========================================================
BALANCED INACTIVE DATASET EXTRACTION LOG
==========================================================

Execution Status                  : SUCCESS

Execution time                    : {pipeline_time / 60:.2f} minutes

----------------------------------------------------------
RESOURCE CONFIGURATION
----------------------------------------------------------

CPUs detected/allocated           : {detected_cpus:,}
DuckDB threads                    : {threads:,}

Detected memory                  : {format_gb(detected_memory)}
DuckDB memory limit              : {memory_limit_gb:.1f} GB

DuckDB temporary directory       : {temp_directory}

DuckDB version                   : {duckdb.__version__}

----------------------------------------------------------
INPUT DATA
----------------------------------------------------------

Active file
    : {ACTIVE_FILE}

Giant inactive file
    : {GIANT_INACTIVE_FILE}

Priority-1 source file
    : {PRIORITY_INACTIVE_FILE}

----------------------------------------------------------
OBSERVATION COUNTS
----------------------------------------------------------

Active observations
    : {total_active_observations:,}

Nominal 1:1 inactive target
    : {requested_target_total:,}

Priority-1 observations
    : {priority_total:,}

Final target
    : {target_total:,}

Final output rows
    : {final_rows:,}

Final unique AID/CID observations
    : {final_unique:,}

----------------------------------------------------------
PRIORITY DEFINITIONS
----------------------------------------------------------

Priority 1
    Active-branch inactive observations
    Mandatory retention

Priority 2
    Exact UniProtKB_ID match

Priority 3
    Exact KO match

Priority 4
    Exact Target_Class match

Priority 5
    Random unrelated observations

Random seed
    : {RANDOM_SEED}

----------------------------------------------------------
FALLBACK CANDIDATES
----------------------------------------------------------

Priority 2 candidates
    : {priority_counts.get(2, 0):,}

Priority 3 candidates
    : {priority_counts.get(3, 0):,}

Priority 4 candidates
    : {priority_counts.get(4, 0):,}

Priority 5 candidates
    : {priority_counts.get(5, 0):,}

----------------------------------------------------------
FALLBACK SELECTION
----------------------------------------------------------

Priority 2 selected
    : {allocations.get(2, 0):,}

Priority 3 selected
    : {allocations.get(3, 0):,}

Priority 4 selected
    : {allocations.get(4, 0):,}

Priority 5 selected
    : {allocations.get(5, 0):,}

Total fallback selected
    : {sum(allocations.values()) if remaining_slots > 0 else 0:,}

----------------------------------------------------------
PRIORITY-1 VALIDATION
----------------------------------------------------------

Priority-1 total
    : {priority_total:,}

Priority-1 retained
    : {priority_retained:,}

Priority-1 missing
    : {missing_priority:,}

Priority-1 retention
    : {retention_percentage:.6f}%

----------------------------------------------------------
OUTPUT
----------------------------------------------------------

Balanced inactive file
    : {BALANCED_INACTIVE_FILE}

Validation
    : PASSED

==========================================================
"""

    append_log(
        log_content
    )

    # ======================================================
    # FINAL REPORT
    # ======================================================

    print(
        "",
        flush=True
    )

    print(
        "==========================================================",
        flush=True
    )

    print(
        "SUCCESS",
        flush=True
    )

    print(
        "==========================================================",
        flush=True
    )

    print(
        f"Final dataset: "
        f"{BALANCED_INACTIVE_FILE}",
        flush=True
    )

    print(
        f"Rows: "
        f"{final_rows:,}",
        flush=True
    )

    print(
        f"Unique AID/CID: "
        f"{final_unique:,}",
        flush=True
    )

    print(
        f"Priority-1 retention: "
        f"{retention_percentage:.6f}%",
        flush=True
    )

    print(
        f"Runtime: "
        f"{pipeline_time / 60:.2f} minutes",
        flush=True
    )

    print(
        f"Log: "
        f"{LOG_FILE}",
        flush=True
    )

    print(
        "==========================================================",
        flush=True
    )

    connection.close()


# ==========================================================
# ENTRY POINT
# ==========================================================

if __name__ == "__main__":

    try:

        main()

    except KeyboardInterrupt:

        print(
            "",
            flush=True
        )

        print(
            "[ERROR] Pipeline interrupted by user.",
            flush=True
        )

        sys.exit(130)

    except Exception as error:

        print(
            "",
            flush=True
        )

        print(
            "[ERROR] Pipeline failed:",
            flush=True
        )

        print(
            str(error),
            flush=True
        )

        raise